mapper.select:
SELECT * FROM memory_store
WHERE tenant_id = #{tenantId} AND scope = #{scope} AND owner_ref = #{ownerRef}
  AND status = 'ACTIVE' LIMIT 1

mapper.update:
UPDATE memory_store SET current_revision = current_revision + 1,
    version = version + 1, modifier_id = #{modifierId}
WHERE tenant_id = #{tenantId} AND id = #{id} AND version = #{version}

UPDATE memory_store
SET maintenance_lease_owner = #{owner}, maintenance_lease_until = #{leaseUntil}
WHERE tenant_id = #{tenantId} AND id = #{id} AND status = 'ACTIVE'
  AND maintenance_lease_dispatch_id = #{dispatchId}
  AND (maintenance_lease_until IS NULL OR maintenance_lease_until < #{now})

UPDATE memory_store
SET maintenance_lease_owner = NULL, maintenance_lease_until = NULL
WHERE tenant_id = #{tenantId} AND id = #{id} AND maintenance_lease_owner = #{owner}

UPDATE memory_store SET maintenance_lease_until = #{leaseUntil}
WHERE tenant_id = #{tenantId} AND id = #{id}
  AND maintenance_lease_owner = #{owner} AND maintenance_lease_until > #{now}

mapper.select:
SELECT maintenance_lease_owner FROM memory_store
WHERE tenant_id = #{tenantId} AND id = #{id}
  AND maintenance_lease_until > #{now}
FOR UPDATE
